import{_ as o,a0 as d,w as p,s as c,I as a,x as e,a1 as i,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"scp 用户的 rsync 遷移指南 | LCTT x X-CMD","titleTemplate":false,"description":"scp 用户的 rsync 遷移指南 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"scp 用户的 rsync 遷移指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"scp 用户的 rsync 遷移指南 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200722 SCP user-s migration guide to rsync","title":"scp 用户的 rsync 遷移指南","tag":"202009","desc":""},"relativePath":"202009/20200722 SCP user-s migration guide to rsync.md","filePath":"[post].md"}'),r={name:"202009/20200722 SCP user-s migration guide to rsync.md"};function h(g,s,k,b,u,y){const n=d("Link");return p(),c("div",null,[s[22]||(s[22]=a("h1",{id:"scp-用户的-rsync-遷移指南",tabindex:"-1"},[e("scp 用户的 rsync 遷移指南 "),a("a",{class:"header-anchor",href:"#scp-用户的-rsync-遷移指南","aria-label":"Permalink to “scp 用户的 rsync 遷移指南”"},"​")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/03/102942u7rxf79a7rsr9txz.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在 ",-1)),i(n,{href:"https://lists.mindrot.org/pipermail/openssh-unix-dev/2019-March/037672.html"},{default:t(()=>[...s[0]||(s[0]=[e("SSH 8.0 預發佈公告",-1)])]),_:1}),s[2]||(s[2]=e("中，OpenSSH 項目表示，他們認為 scp 協議已經過時，不靈活，而且不容易修復，然後他們繼而推薦使用 ",-1)),s[3]||(s[3]=a("code",null,"sftp",-1)),s[4]||(s[4]=e(" 或 ",-1)),s[5]||(s[5]=a("code",null,"rsync",-1)),s[6]||(s[6]=e(" 來進行文件傳輸。",-1))]),s[24]||(s[24]=l(`<p>然而，很多用户都是從小用着 <code>scp</code> 命令長大的，所以對 <code>rsync</code> 並不熟悉。此外，<code>rsync</code> 可以做的事情也遠不止複製文件，這可能會給菜鳥們留下複雜和難以掌握的印象。尤其是，<code>scp</code> 命令的標誌大體上可以直接對應到 <code>cp</code> 命令的標誌，而 <code>rsync</code> 命令的標誌卻和它大相逕庭。</p><p>本文將為熟悉 <code>scp</code> 的人提供一個介紹和過渡的指南。讓我們跳進最常見的場景：複製文件和複製目錄。</p><h3 id="複製文件" tabindex="-1">複製文件 <a class="header-anchor" href="#複製文件" aria-label="Permalink to “複製文件”">​</a></h3><p>對於複製單個文件而言，<code>scp</code> 和 <code>rsync</code> 命令實際上是等價的。比方説，你需要把 <code>foo.txt</code> 傳到你在名為 <code>server</code> 的服務器上的主目錄下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp foo.txt me@server:/home/me/</span></span></code></pre></div><p>相應的 <code>rsync</code> 命令只需要輸入 <code>rsync</code> 取代 <code>scp</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync foo.txt me@server:/home/me/</span></span></code></pre></div><h3 id="複製目錄" tabindex="-1">複製目錄 <a class="header-anchor" href="#複製目錄" aria-label="Permalink to “複製目錄”">​</a></h3><p>對於複製目錄，就有了很大的分歧，這也解釋了為什麼 <code>rsync</code> 會被認為比 <code>scp</code> 更復雜。如果你想把 <code>bar</code> 目錄複製到 <code>server</code> 服務器上，除了指定 <code>ssh</code> 信息外，相應的 <code>scp</code> 命令和 <code>cp</code> 命令一模一樣。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -r bar/ me@server:/home/me/</span></span></code></pre></div><p>對於 <code>rsync</code>，考慮的因素比較多，因為它是一個比較強大的工具。首先，我們來看一下最簡單的形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -r bar/ me@server:/home/me/</span></span></code></pre></div><p>看起來很簡單吧？對於只包含目錄和普通文件的簡單情況，這就可以了。然而，<code>rsync</code> 更在意發送與主機系統中一模一樣的文件。讓我們來創建一個稍微複雜一些，但並不罕見的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 創建多級目錄結構</span></span>
<span class="line"><span>$ mkdir -p bar/baz</span></span>
<span class="line"><span># 在其根目錄下創建文件</span></span>
<span class="line"><span>$ touch bar/foo.txt</span></span>
<span class="line"><span># 現在創建一個符號鏈接指回到該文件</span></span>
<span class="line"><span>$ cd bar/baz</span></span>
<span class="line"><span>$ ln -s ../foo.txt link.txt</span></span>
<span class="line"><span># 返回原位置</span></span>
<span class="line"><span>$ cd -</span></span></code></pre></div><p>現在我們有了一個如下的目錄樹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bar</span></span>
<span class="line"><span>├── baz</span></span>
<span class="line"><span>│   └── link.txt -&gt; ../foo.txt</span></span>
<span class="line"><span>└── foo.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 directory, 2 files</span></span></code></pre></div><p>如果我們嘗試上面的命令來複制 <code>bar</code>，我們會注意到非常不同的（並令人驚訝的）結果。首先，我們來試試 <code>scp</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -r bar/ me@server:/home/me/</span></span></code></pre></div><p>如果你 <code>ssh</code> 進入你的服務器，看看 <code>bar</code> 的目錄樹，你會發現它和你的主機系統有一個重要而微妙的區別：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bar</span></span>
<span class="line"><span>├── baz</span></span>
<span class="line"><span>│   └── link.txt</span></span>
<span class="line"><span>└── foo.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 directory, 2 files</span></span></code></pre></div><p>請注意，<code>link.txt</code> 不再是一個符號鏈接，它現在是一個 <code>foo.txt</code> 的完整副本。如果你習慣於使用 <code>cp</code>，這可能會是令人驚訝的行為。如果你嘗試使用 <code>cp -r</code> 複製 <code>bar</code> 目錄，你會得到一個新的目錄，裏面的符號鏈接和 <code>bar</code> 的一樣。現在如果我們嘗試使用之前的 <code>rsync</code> 命令，我們會得到一個警告：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -r bar/ me@server:/home/me/</span></span>
<span class="line"><span>skipping non-regular file &quot;bar/baz/link.txt&quot;</span></span></code></pre></div><p><code>rsync</code> 警告我們它發現了一個非常規文件，並正在跳過它。因為你沒有告訴它可以複製符號鏈接，所以它忽略了它們。<code>rsync</code> 在手冊中有一節“符號鏈接”，解釋了所有可能的行為選項。在我們的例子中，我們需要添加 <code>-links</code> 標誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -r --links bar/ me@server:/home/me/</span></span></code></pre></div><p>在遠程服務器上，我們看到這個符號鏈接是作為一個符號鏈接複製過來的。請注意，這與 <code>scp</code> 複製符號鏈接的方式不同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bar/</span></span>
<span class="line"><span>├── baz</span></span>
<span class="line"><span>│   └── link.txt -&gt; ../foo.txt</span></span>
<span class="line"><span>└── foo.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 directory, 2 files</span></span></code></pre></div><p>為了省去一些打字工作，並利用更多的文件保護選項，在複製目錄時可以使用歸檔標誌 <code>-archive</code>（簡稱 <code>-a</code>）。該歸檔標誌將做大多數人所期望的事情，因為它可以實現遞歸複製、符號鏈接複製和許多其他選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -a bar/ me@server:/home/me/</span></span></code></pre></div><p>如果你感興趣的話，<code>rsync</code> 手冊頁有關於存檔標誌的深入解釋。</p><h3 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to “注意事項”">​</a></h3><p>不過，使用 <code>rsync</code> 有一個注意事項。使用 <code>scp</code> 比使用 <code>rsync</code> 更容易指定一個非標準的 ssh 端口。例如，如果 <code>server</code> 使用 8022 端口的 SSH 連接，那麼這些命令就會像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -P 8022 foo.txt me@server:/home/me/</span></span></code></pre></div><p>而在使用 <code>rsync</code> 時，你必須指定要使用的“遠程 shell”命令，默認是 <code>ssh</code>。你可以使用 <code>-e</code> 標誌來指定。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -e &#39;ssh -p 8022&#39; foo.txt me@server:/home/me/</span></span></code></pre></div><p><code>rsync</code> 會使用你的 <code>ssh</code> 配置；但是，如果你經常連接到這個服務器，你可以在你的 <code>~/.ssh/config</code> 文件中添加以下代碼。這樣你就不需要再為 <code>rsync</code> 或 <code>ssh</code> 命令指定端口了！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host server</span></span>
<span class="line"><span>    Port 8022</span></span></code></pre></div><p>另外，如果你連接的每一台服務器都在同一個非標準端口上運行，你還可以配置 <code>RSYNC_RSH</code> 環境變量。</p><h3 id="為什麼你還是應該切換到-rsync" tabindex="-1">為什麼你還是應該切換到 rsync？ <a class="header-anchor" href="#為什麼你還是應該切換到-rsync" aria-label="Permalink to “為什麼你還是應該切換到 rsync？”">​</a></h3><p>現在我們已經介紹了從 <code>scp</code> 切換到 <code>rsync</code> 的日常使用案例和注意事項，讓我們花一些時間來探討一下為什麼你可能想要使用 <code>rsync</code> 的優點。很多人在很久以前就已經開始使用 <code>rsync</code> 了，就是因為這些優點。</p><h4 id="即時壓縮" tabindex="-1">即時壓縮 <a class="header-anchor" href="#即時壓縮" aria-label="Permalink to “即時壓縮”">​</a></h4><p>如果你和服務器之間的網絡連接速度較慢或有限，<code>rsync</code> 可以花費更多的 CPU 處理能力來節省網絡帶寬。它通過在發送數據之前對數據進行即時壓縮來實現。壓縮可以用 <code>-z</code> 標誌來啓用。</p><h4 id="差量傳輸" tabindex="-1">差量傳輸 <a class="header-anchor" href="#差量傳輸" aria-label="Permalink to “差量傳輸”">​</a></h4><p><code>rsync</code> 也只在目標文件與源文件不同的情況下複製文件。這可以在目錄中遞歸地工作。例如，如果你拿我們上面的最後一個 <code>bar</code> 的例子，並多次重新運行那個 <code>rsync</code> 命令，那麼在最初的傳輸之後就不會有任何傳輸。如果你知道你會重複使用這些命令，例如備份到 U 盤，那麼使用 <code>rsync</code> 即使是進行本地複製也是值得的，因為這個功能可以節省處理大型數據集的大量的時間。</p><h4 id="同步" tabindex="-1">同步 <a class="header-anchor" href="#同步" aria-label="Permalink to “同步”">​</a></h4><p>顧名思義，<code>rsync</code> 可以做的不僅僅是複製數據。到目前為止，我們只演示瞭如何使用 <code>rsync</code> 複製文件。如果你想讓 <code>rsync</code> 把目標目錄變成源目錄的樣子，你可以在 <code>rsync</code> 中添加刪除標誌 <code>-delete</code>。這個刪除標誌使得 <code>rsync</code> 將從源目錄中複製不存在於目標目錄中的文件，然後它將刪除目標目錄中不存在於源目錄中的文件。結果就是目標目錄和源目錄完全一樣。相比之下，<code>scp</code> 只會在目標目錄下添加文件。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>對於簡單的使用情況，<code>rsync</code> 並不比老牌的 <code>scp</code> 工具複雜多少。唯一顯著的區別是在遞歸複製目錄時使用 <code>-a</code> 而不是 <code>-r</code>。然而，正如我們看到的，<code>rsync</code> 的 <code>-a</code> 標誌比 <code>scp</code> 的 <code>-r</code> 標誌更像 <code>cp</code> 的 <code>-r</code> 標誌。</p><p>希望通過這些新命令，你可以加快你的文件傳輸工作流程。</p><hr>`,49)),a("p",null,[s[8]||(s[8]=e("via: ",-1)),i(n,{href:"https://fedoramagazine.org/scp-users-migration-guide-to-rsync/"},{default:t(()=>[...s[7]||(s[7]=[e("https://fedoramagazine.org/scp-users-migration-guide-to-rsync/",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=e("作者：",-1)),i(n,{href:"https://fedoramagazine.org/author/chasinglogic/"},{default:t(()=>[...s[9]||(s[9]=[e("chasinglogic",-1)])]),_:1}),s[14]||(s[14]=e(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[10]||(s[10]=[e("lujun9972",-1)])]),_:1}),s[15]||(s[15]=e(" 譯者：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1}),s[16]||(s[16]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[17]||(s[17]=[e("LCTT",-1)])]),_:1}),s[20]||(s[20]=e(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[18]||(s[18]=[e("Linux中國",-1)])]),_:1}),s[21]||(s[21]=e(" 榮譽推出",-1))])])}const C=o(r,[["render",h]]);export{x as __pageData,C as default};
